struct State{GCase c;Buffer table,failed,echo;std::array<std::unique_ptr<Buffer>,4>keys;std::array<cudaStream_t,4>streams;uint64_t*nfbase,*nf;State(const GCase&c):c(c),table(c.entries*(c.ip+1)),failed(c.n*c.ip),echo(c.n*c.ip){for(int i=0;i<4;i++){keys[i]=std::make_unique<Buffer>(65536);CK(cudaStreamCreate(&streams[i]));}CK(cudaMalloc(&nfbase,34*8));nf=nfbase+32;CK(cudaMemset(nfbase,165,34*8));}~State(){for(auto s:streams)cudaStreamDestroy(s);cudaFree(nfbase);}void reset(){table.reset(0);failed.reset(165);echo.reset(165);for(auto&k:keys)k->reset(165);CK(cudaMemset(nf,0,8));CK(cudaDeviceSynchronize());}};
void dispatch(State&s,unsigned stream,unsigned n){auto t=s.table.data,k=s.keys[stream]->data,fail=s.failed.data;switch(s.c.ip){case 1:addToTable<1>((KeyValuePair<1>*)t,s.c.entries,(Key<1>*)k,n,s.streams[stream],(Key<1>*)fail,s.nf,s.c.n);break;case 2:addToTable<2>((KeyValuePair<2>*)t,s.c.entries,(Key<2>*)k,n,s.streams[stream],(Key<2>*)fail,s.nf,s.c.n);break;case 4:addToTable<4>((KeyValuePair<4>*)t,s.c.entries,(Key<4>*)k,n,s.streams[stream],(Key<4>*)fail,s.nf,s.c.n);break;case 6:addToTable<6>((KeyValuePair<6>*)t,s.c.entries,(Key<6>*)k,n,s.streams[stream],(Key<6>*)fail,s.nf,s.c.n);break;case 10:addToTable<10>((KeyValuePair<10>*)t,s.c.entries,(Key<10>*)k,n,s.streams[stream],(Key<10>*)fail,s.nf,s.c.n);break;default:throw std::runtime_error("unsupported harness key width");}}
