Result run(State&s,int trial,const std::string&folder,bool save){auto&c=s.c;s.reset();Result out;auto initial=s.table.read(),initfail=s.failed.read();out.prefix.insert(out.prefix.end(),initial.begin()+8,initial.end()-8);out.prefix.insert(out.prefix.end(),initfail.begin()+8,initfail.end()-8);uint64_t initialcount;CK(cudaMemcpy(&initialcount,s.nf,8,cudaMemcpyDeviceToHost));out.prefix.push_back(initialcount);std::vector<uint32_t>table(c.entries*(c.ip+1)),hist(512,0),selected;uint64_t count,unique=0,total=0,below=0;unsigned capacity=65536/c.ip,bundle=0;CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(unsigned offset=0;offset<c.n;offset+=capacity,bundle++){auto n=std::min(capacity,c.n-offset),stream=bundle%4;CK(cudaMemcpyAsync(s.keys[stream]->data,c.keys.data()+offset*c.ip,n*c.ip*4,cudaMemcpyHostToDevice,s.streams[stream]));CK(cudaMemcpyAsync(s.echo.data+offset*c.ip,s.keys[stream]->data,n*c.ip*4,cudaMemcpyDeviceToDevice,s.streams[stream]));dispatch(s,stream,n);}CK(cudaDeviceSynchronize());CK(cudaMemcpy(table.data(),s.table.data,table.size()*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(&count,s.nf,8,cudaMemcpyDeviceToHost));for(unsigned i=0;i<c.entries;i++){auto p=table.data()+i*(c.ip+1);auto n=p[c.ip];if(n){unique++;total+=n;hist[n<512?n:0]++;if(n>=c.threshold)selected.insert(selected.end(),p,p+c.ip+1);else below++;}}out.seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();auto tab=s.table.read(),failed=s.failed.read(),echo=s.echo.read();std::array<std::vector<uint32_t>,4>keydata;for(int i=0;i<4;i++)keydata[i]=s.keys[i]->read();uint64_t nf[3];CK(cudaMemcpy(nf,s.nf-1,24,cudaMemcpyDeviceToHost));out.prefix.insert(out.prefix.end(),echo.begin()+8,echo.end()-8);std::vector<uint64_t>raw={c.k,c.ip,c.n,c.entries,65536,bundle};raw.insert(raw.end(),tab.begin(),tab.end());for(auto&a:keydata)raw.insert(raw.end(),a.begin(),a.end());raw.insert(raw.end(),failed.begin(),failed.end());raw.insert(raw.end(),echo.begin(),echo.end());raw.insert(raw.end(),nf,nf+3);std::string rawpath=folder+"/cuda_"+std::to_string(getpid())+"_trial"+std::to_string(trial)+"_k"+std::to_string(c.k)+".bin";if(save){std::ofstream f(rawpath,std::ios::binary);f.write((char*)raw.data(),raw.size()*8);f.close();printf("STUDY_RAW_ARTIFACT {\"trial\":%d,\"k\":%u,\"path\":\"%s\",\"dtype\":\"uint64\",\"count\":%zu}\n",trial,c.k,rawpath.c_str(),raw.size());}std::vector<uint32_t>permutation;auto canonical=canonical_extract(c,table,permutation);canonical.resize(c.entries*(c.ip+1));out.output.insert(out.output.end(),canonical.begin(),canonical.end());out.output.insert(out.output.end(),hist.begin(),hist.end());out.output.push_back(selected.size()/(c.ip+1));std::vector<std::vector<uint32_t>>rows;for(size_t i=0;i<selected.size();i+=c.ip+1)rows.emplace_back(selected.begin()+i,selected.begin()+i+c.ip+1);std::sort(rows.begin(),rows.end());for(auto&a:rows)out.output.insert(out.output.end(),a.begin(),a.end());out.output.insert(out.output.end(),{unique,total,below});out.output.insert(out.output.end(),failed.begin()+8,failed.end()-8);out.output.push_back(count);for(auto*a:{&tab,&keydata[0],&keydata[1],&keydata[2],&keydata[3],&failed,&echo}){out.output.insert(out.output.end(),a->begin(),a->begin()+8);out.output.insert(out.output.end(),a->end()-8,a->end());}out.output.push_back(nf[0]);out.output.push_back(nf[2]);if(save){std::ofstream f(rawpath+".permutation.u32",std::ios::binary);f.write((char*)permutation.data(),permutation.size()*4);}return out;}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("persistent raw evidence directory required");std::filesystem::create_directories(argv[1]);auto cs=load_cases();std::vector<std::unique_ptr<State>>states;for(auto&c:cs)states.emplace_back(std::make_unique<State>(c));for(auto&s:states)run(*s,0,argv[1],false);for(int trial=1;trial<=5;trial++){std::vector<uint64_t>prefix,outputs;double seconds=0;for(auto&s:states){auto r=run(*s,trial,argv[1],true);prefix.insert(prefix.end(),r.prefix.begin(),r.prefix.end());outputs.insert(outputs.end(),r.output.begin(),r.output.end());seconds+=r.seconds;}prefix.insert(prefix.end(),outputs.begin(),outputs.end());std::string path="trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)prefix.data(),prefix.size()*8);f.close();bool ok=check_record(prefix.data(),prefix.size());printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%s,\"max_rel_error\":%s,\"timing_region\":\"sum5_preallocated_active_GPU_counting_upload_echo_insert_fulltable_extract_histogram_threshold\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",prefix.size(),ok?"0":"null",ok?"0":"null",path.c_str(),prefix.size());if(!ok)return 1;}return 0;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
